const triggerData = $input.item.json || {};
const body = triggerData.body || triggerData.payload || triggerData || {};
const authUser = triggerData.user || {};
const userId = Number(authUser.user_id || authUser.id);
const includeDeleted = Boolean(body.include_deleted && userId === 1);

return {
  json: {
    includeDeleted
  }
};

const items = $input.all();
const lojas = items.map(item => {
  const loja = { ...item.json };
  if (loja.config_json) {
    const config = { ...loja.config_json };
    if (config.evolutionapi) {
      const { apikey, token, ...safeEvolution } = config.evolutionapi;
      config.evolutionapi = {
        ...safeEvolution,
        hasApiKey: Boolean(apikey),
        hasToken: Boolean(token)
      };
    }
    loja.config_json = config;
  }
  return loja;
});

return {
  json: {
    ok: true,
    lojas: lojas
  }
};
